import{c as a,Q as i,j as l,m as n}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"Init","description":"","frontmatter":{},"headers":[{"level":1,"title":"Init","slug":"init"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Init-85.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Init-85.md"}'),e={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Kernel侧接口/Init-85.md"};function s(p,t,d,r,T,o){return i(),l("div",null,[...t[0]||(t[0]=[n(`<h1 id="init" tabindex="-1">Init <a class="header-anchor" href="#init" aria-label="Permalink to &quot;Init&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>Tiling参数传入栈地址的接口</th><th>Tiling参数传入GM地址的接口</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Init主要用于对Matmul对象中的Tiling数据进行初始化，根据Tiling参数进行资源划分，Tiling参数的具体介绍请参考<a href="./../Matmul-Tiling侧接口/Matmul-Tiling侧接口.html">Matmul Tiling侧接口</a>。</p><p>开发者可以先通过<a href="./REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>不传入Tiling参数对单个Matmul对象进行初始化，后续通过Init接口单独传入Tiling参数，对Matmul对象中的Tiling数据进行调整。比如，Tiling参数可变的场景下，可以通过多次调用Init来重新设置Tiling参数。</p><p>不需要Tiling变更的场景下，推荐使用<a href="./REGIST_MATMUL_OBJ.html">REGIST_MATMUL_OBJ</a>传入Tiling参数进行初始化。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>Tiling参数传入栈地址</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Init(const TCubeTiling* __restrict cubeTiling, TPipe* tpipe = nullptr)</span></span></code></pre></div></li><li><p>Tiling参数传入GM地址</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Init(const __gm__ TCubeTiling* gmCubeTiling, TPipe* tpipe = nullptr)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> Tiling参数传入栈地址接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>cubeTiling</td><td>输入</td><td>Matmul Tiling参数，TCubeTiling结构体定义请参见表1 TCubeTiling结构说明。 Tiling参数可以通过host侧GetTiling接口获取，并传递到kernel侧使用。在kernel侧调用GET_TILING_DATA实现将Tiling参数搬运到AI Core内的栈空间中，本接口传入Tiling参数中TCubeTiling结构体的栈地址。</td></tr><tr><td>tpipe</td><td>输入</td><td>Tpipe对象。</td></tr></tbody></table><p><strong>表 2</strong> Tiling参数传入GM地址接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>gmCubeTiling</td><td>输入</td><td>Matmul Tiling参数，该参数指向gm上的一块内存地址，其中的数据类型是TCubeTiling结构体，TCubeTiling结构体定义请参见表1 TCubeTiling结构说明。 Tiling参数可以通过host侧GetTiling接口获取，并传递到kernel侧使用。在kernel侧调用GET_TILING_DATA_PTR_WITH_STRUCT获取gm上Tiling参数的指针，本接口传入Tiling参数中TCubeTiling结构体的GM地址。</td></tr><tr><td>tpipe</td><td>输入</td><td>Tpipe对象。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>Tiling参数传入栈地址的接口：</p><p>无。</p></li><li><p>Tiling参数传入GM地址的接口：</p><ul><li>仅支持Matmul Tiling参数的<a href="./GetMatmulApiTiling.html#section618mcpsimp">部分常量化</a>场景。</li><li>不支持CPU域调试。</li></ul></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>Tiling参数传入栈地址</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET_TILING_DATA(tilingData, tiling);</span></span>
<span class="line"><span>// ...</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span>mm.Init(&amp;(tiling.cubeTilingData));</span></span></code></pre></div></li><li><p>Tiling参数传入GM地址</p><ul><li><p>纯Cube模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ASCENDC_CUBE_ONLY</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GET_TILING_DATA_PTR_WITH_STRUCT(MatmulCustomTilingData, tilingDataPtr, tiling);</span></span>
<span class="line"><span>KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_AIC_ONLY);</span></span>
<span class="line"><span>// ...</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm);</span></span>
<span class="line"><span>mm.Init(&amp;(tilingDataPtr-&gt;cubeTilingData));</span></span></code></pre></div></li><li><p>MIX模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET_TILING_DATA_PTR_WITH_STRUCT(MatmulCustomTilingData, tilingDataPtr, tiling);</span></span>
<span class="line"><span>KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);</span></span>
<span class="line"><span>// ...</span></span>
<span class="line"><span>// MIX模式下，只调用REGIST_MATMUL_OBJ接口，传入Tiling参数的GM地址，不需调用Init接口</span></span>
<span class="line"><span>REGIST_MATMUL_OBJ(&amp;pipe, GetSysWorkSpacePtr(), mm, &amp;(tilingDataPtr-&gt;cubeTilingData));</span></span></code></pre></div></li></ul></li></ul>`,20)])])}const c=a(e,[["render",s]]);export{h as __pageData,c as default};
